from vault.db import add_entry, get_entry, delete_entry
from vault.exceptions import KeyNotFoundError


def test_get_unknown_key_raises(init_db) -> None:
    """Getting a non-existent key raises KeyNotFoundError."""
    try:
        get_entry(init_db, "no_such_key")
        assert False, "Expected KeyNotFoundError"
    except KeyNotFoundError as e:
        assert "no_such_key" in str(e)


def test_delete_unknown_key_raises(init_db) -> None:
    """Deleting a non-existent key raises KeyNotFoundError."""
    try:
        delete_entry(init_db, "no_such_key")
        assert False, "Expected KeyNotFoundError"
    except KeyNotFoundError as e:
        assert "no_such_key" in str(e)


def test_get_existing_key_after_add(init_db) -> None:
    """Adding then getting a key returns the correct value."""
    add_entry(init_db, "known", "my_secret")
    entry = get_entry(init_db, "known")
    assert entry["value"] == "my_secret"
